"use strict";
function roleAllowsMaintain(id){return session.account.administrator||projects.find(p=>p.id===id)?.members[session.account.id]==='Maintainer';}
function controlsHTML(t){if(t.protected||!roleAllowsWrite(t.projectId))return '';const terminal=['Done','Cancelled'].includes(t.status);return `<div class="record-controls">${t.status==='Todo'&&t.kind!=='goal'?'<button type="button" class="secondary" data-control="dependencies">Prerequisites</button>':''}${roleAllowsMaintain(t.projectId)?`<button type="button" class="secondary" data-control="transfer">Transfer</button><button type="button" class="secondary" data-control="archive">${t.archived?'Unarchive':'Archive'}</button><button type="button" class="secondary" data-control="delete">${t.deleted?'Restore':'Delete'}</button>`:''}${!terminal?'<button type="button" class="secondary" data-control="cancel">Cancel work</button>':(t.status==='Cancelled'||t.kind==='task')&&((!t.agent&&t.kind==='task')||roleAllowsMaintain(t.projectId))?'<button type="button" class="secondary" data-control="reopen">Reopen selected work</button>':''}</div>`;}
function bindControls(t,dialog){dialog.querySelectorAll('[data-control]').forEach(button=>button.onclick=()=>controlForm(t,button.dataset.control));}
function controlForm(t,kind){if(byId('editor').dataset.dirty==='true'){notice('Save changes before changing record state.');return;}byId('editor').close();let title,body,submit,operation,build;const identity={id:t.id,expectedVersion:t.version};
if(kind==='dependencies'){title='Prerequisites';const candidates=tickets.filter(x=>x.id!==t.id&&x.projectId===t.projectId&&x.kind!=='goal'&&x.status!=='Cancelled');const missing=t.dependencies.filter(id=>!candidates.some(x=>x.id===id));body=`<label>Required tickets<select name="dependencies" multiple size="7">${candidates.map(x=>`<option value="${x.id}" ${t.dependencies.includes(x.id)?'selected':''}>#${x.id} · ${escapeHTML(x.title)} (${x.status})</option>`).join('')}${missing.map(id=>`<option value="${id}" selected>#${id} · retained prerequisite</option>`).join('')}</select></label>`;submit='Save prerequisites';operation='setDependencies';build=form=>({...identity,dependencies:form.getAll('dependencies').map(Number)});}
else if(kind==='transfer'){title='Transfer ticket';const destinations=projects.filter(p=>p.id!==t.projectId&&roleAllowsMaintain(p.id));body=`<p>${escapeHTML(t.title)}${t.kind==='task'?'':' and all descendants, including hidden work'}.</p><label>Destination project<select name="destinationProjectId" required>${destinations.map(p=>`<option value="${p.id}">${escapeHTML(p.name)}</option>`).join('')}</select></label><label>Destination parent ID<input name="parentId" type="number" min="1" placeholder="Use destination Unassigned default"></label>`;submit='Transfer';operation='transferTicket';build=form=>({...identity,destinationProjectId:Number(form.get('destinationProjectId')),parentId:Number(form.get('parentId'))});}
else if(kind==='cancel'){title='Cancel work';body=`<p>${escapeHTML(t.title)}${t.kind==='task'?'':' and unfinished descendants'} will be cancelled. Retained work and history remain available.</p><label>Reason<textarea name="reason" rows="3" maxlength="20000"></textarea></label>`;submit='Cancel work';operation='cancelTicket';build=form=>({...identity,reason:form.get('reason')});}
else if(kind==='reopen'){title='Reopen selected work';body=`<p>${escapeHTML(t.title)}</p><p>${t.kind==='task'?'Return to inactive Todo. Agent work requires fresh refinement and scope acceptance.':'Only this container reopens; child cancellations remain unchanged.'}</p>`;submit='Reopen';operation='reopenTicket';build=()=>identity;}
else{const field=kind==='archive'?'archived':'deleted';const value=!t[field];title=kind==='archive'?(value?'Archive ticket':'Unarchive ticket'):(value?'Delete ticket':'Restore ticket');body=`<p>${escapeHTML(t.title)}</p><p>Only this selected record changes. Children keep their current visibility and history.</p>`;submit=title;operation='setTicketVisibility';build=()=>({...identity,[field]:value});}
const dialog=openDialog(title,body,submit);byId('editor-form').onsubmit=async e=>{e.preventDefault();try{await api(operation,build(new FormData(e.currentTarget)));dialog.close();await workspace();notice(title+' saved');}catch(error){showError(error);}};}
async function hiddenTickets(){try{const hidden=(await pages('listTickets',{...(projectId?{projectId}:{}),includeHidden:true})).filter(t=>t.archived||t.deleted);const dialog=openDialog('Hidden tickets',`<div>${hidden.map(t=>`<button type="button" class="work-row" data-hidden-ticket="${t.id}"><span>#${t.id}</span><span>${escapeHTML(t.title)}</span><span>${t.deleted?'Deleted':'Archived'}</span></button>`).join('')||'<p>No hidden tickets.</p>'}</div>`,'Close');dialog.querySelector('button[type=submit]').onclick=e=>{e.preventDefault();dialog.close();};dialog.querySelectorAll('[data-hidden-ticket]').forEach(button=>button.onclick=()=>{dialog.close();editTicket(Number(button.dataset.hiddenTicket));});}catch(error){showError(error);}}
function passwordForm(){const dialog=openDialog('Change password','<label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label>','Change and sign out');byId('editor-form').onsubmit=async e=>{e.preventDefault();try{await api('changePassword',Object.fromEntries(new FormData(e.currentTarget)));dialog.close();loadGeneration++;session=null;projects=[];tickets=[];login();notice('Password changed. Sign in again.');}catch(error){showError(error);}};}
